1	<#
2	.SYNOPSIS
3	    将所有 Claude Code 项目的 memory 和对话历史同步到本仓库。
4	.DESCRIPTION
5	    扫描 ~/.claude/projects/ 下所有项目，将 memory 和 session JSONL
6	    以项目名为子目录复制到本仓库，保持项目隔离。
7	#>
8	
9	$claudeProjects = Join-Path $env:USERPROFILE ".claude\projects"
10	$memoryRoot = Join-Path $PSScriptRoot "memory"
11	$sessionsRoot = Join-Path $PSScriptRoot "sessions"
12	
13	if (-not (Test-Path $memoryRoot)) {
14	    New-Item -ItemType Directory -Force $memoryRoot | Out-Null
15	}
16	if (-not (Test-Path $sessionsRoot)) {
17	    New-Item -ItemType Directory -Force $sessionsRoot | Out-Null
18	}
19	
20	Get-ChildItem $claudeProjects -Directory | ForEach-Object {
21	    $projName = $_.Name
22	
23	    $memSrc = Join-Path $_.FullName "memory"
24	    if (Test-Path $memSrc) {
25	        $files = Get-ChildItem $memSrc -File
26	        if ($files.Count -gt 0) {
27	            $projDir = Join-Path $memoryRoot $projName
28	            if (-not (Test-Path $projDir)) {
29	                New-Item -ItemType Directory -Force $projDir | Out-Null
30	            }
31	            Copy-Item "$memSrc\*" $projDir -Force -Recurse
32	            Write-Output "Memory: $projName ($($files.Count) files)"
33	        }
34	    }
35	
36	    $jsonls = Get-ChildItem $_.FullName -Filter "*.jsonl" -File
37	    if ($jsonls.Count -gt 0) {
38	        $projDir = Join-Path $sessionsRoot $projName
39	        if (-not (Test-Path $projDir)) {
40	            New-Item -ItemType Directory -Force $projDir | Out-Null
41	        }
42	        Copy-Item ($jsonls | ForEach-Object { $_.FullName }) $projDir -Force
43	        Write-Output "Sessions: $projName ($($jsonls.Count) files)"
44	    }
45	}
46	
47	Write-Output "Done."
48

